// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Ensure caller is owner
        vm.prank(c.owner());
        // Bound value to avoid gas issues
        value = bound(value, 0, address(c).balance);
        // Ensure we have enough balance
        vm.deal(address(c), value);
        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));
        // Assert that owner remains unchanged from the initial deployer
        assertTrue(c.owner() == address(this));
    }
}

